//! The scanner against 0.5.1: `spec/verbatim/tools/shell-scan-corpus.jsonl.gz` holds what the
//! fork's `ShellParse.scan` returned for every input its scanner tests use (generated by
//! `script/shell-corpus.sh`), with home `/home/tester`, cwd `/work/project`, env
//! `{HOME, USER=tester, PROJECTS=/srv/projects}` and PowerShell at `/usr/bin/pwsh`.

#[cfg(unix)]
use std::io::Read;

use serde_json::Value;

use super::super::parse::{self, Host};

#[cfg(unix)]
const CORPUS: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../spec/verbatim/tools/shell-scan-corpus.jsonl.gz"
));

fn shell_path(shell: &str) -> &'static str {
    match shell {
        "bash" => "/bin/bash",
        "zsh" => "/bin/zsh",
        "posix" => "/bin/sh",
        _ => "/usr/bin/pwsh",
    }
}

fn host_env(name: &str) -> Option<String> {
    match name {
        "HOME" => Some("/home/tester".into()),
        "USER" => Some("tester".into()),
        "PROJECTS" => Some("/srv/projects".into()),
        _ => None,
    }
}

fn actual(shell: &str, command: &str) -> Value {
    let host = Host {
        home: "/home/tester",
        env: &host_env,
    };
    match parse::scan(command, shell_path(shell), "/work/project", &host) {
        Ok(parsed) => serde_json::json!({
            "commands": parsed.commands.iter().map(|c| [&c.resource, &c.save]).collect::<Vec<_>>(),
            "directories": parsed.directories,
        }),
        Err(reason) => serde_json::json!({ "error": reason.to_string() }),
    }
}

// The corpus was produced on Linux; Windows matches wildcards case-insensitively and expands `~\`.
#[cfg(unix)]
#[test]
fn matches_the_0_5_1_corpus() {
    let mut text = String::new();
    flate2::read::GzDecoder::new(CORPUS)
        .read_to_string(&mut text)
        .expect("corpus decompresses");
    let mut failures = Vec::new();
    let mut total = 0;
    for line in text.lines() {
        let mut row: Value = serde_json::from_str(line).expect("corpus row is JSON");
        let shell = row["shell"].as_str().unwrap_or_default().to_string();
        let command = row["command"].as_str().unwrap_or_default().to_string();
        let row = row.as_object_mut().expect("row is an object");
        row.remove("shell");
        row.remove("command");
        let expected = Value::Object(row.clone());
        let got = actual(&shell, &command);
        total += 1;
        if got != expected {
            failures.push(format!(
                "{shell} {command:?}\n  expected {expected}\n  actual   {got}"
            ));
        }
    }
    assert!(total > 40_000, "corpus too small: {total}");
    assert!(
        failures.is_empty(),
        "{} of {total} differ:\n{}",
        failures.len(),
        failures
            .iter()
            .take(40)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn opaque_commands_name_their_reason() {
    let host = Host {
        home: "/home/tester",
        env: &host_env,
    };
    let error = parse::scan("echo \"", "/bin/bash", "/w", &host).unwrap_err();
    assert_eq!(
        parse::error_text(error),
        "Portable shell scanner cannot analyze command: unterminated-quote"
    );
}

#[test]
fn derived_cases() {
    let cases = [
        (
            "bash",
            "git status && npm run test -- --watch",
            r#"{"commands":[["git status","git status *"],["npm run test -- --watch","npm run test *"]],"directories":[]}"#,
        ),
        (
            "bash",
            "FOO=1 bun test",
            r#"{"commands":[["FOO=1 bun test","bun test *"]],"directories":[]}"#,
        ),
        ("bash", "export A=1", r#"{"commands":[],"directories":[]}"#),
        (
            "bash",
            "cd ~/x && ls",
            r#"{"commands":[["ls","ls *"]],"directories":["/home/tester/x"]}"#,
        ),
        (
            "bash",
            "cd $HOME",
            r#"{"commands":[["cd $HOME","cd *"]],"directories":[]}"#,
        ),
        (
            "posix",
            "echo `date`",
            r#"{"commands":[["echo `date`","echo *"],["date","date *"]],"directories":[]}"#,
        ),
        (
            "powershell",
            "Set-Location $env:PROJECTS; git status",
            r#"{"commands":[["git status","git status *"]],"directories":["/srv/projects"]}"#,
        ),
    ];
    for (shell, command, expected) in cases {
        let expected: Value = serde_json::from_str(expected).unwrap();
        assert_eq!(actual(shell, command), expected, "{shell} {command}");
    }
}
